begin;
insert into public.ma_configuracao(id,documento) values('contatos',$catalog${"title": "Contatos e atendimentos", "description": "Acompanhe cada contato desde a primeira mensagem, a triagem e a confirmação do atendimento.", "poll_ms": 8000, "page_size": 25, "categories": {"colaborador": {"collection": "voluntarios"}, "relato": {"collection": "relatos"}, "solicitacao": {"collection": "solicitacoes"}}, "stages": [{"key": "menu", "label": "Aguardando triagem"}, {"key": "identity", "label": "Identificação"}, {"key": "question", "label": "Preenchendo informações"}, {"key": "review", "label": "Aguardando confirmação"}, {"key": "done", "label": "Confirmado"}, {"key": "manual", "label": "Cadastro manual"}], "identity_nodes": ["nome", "tipo_pessoa", "endereco", "telefone"], "fields": {"name": ["nome"], "phone": ["telefone"], "address": ["endereco", "endereco_ocorrencia"], "neighborhood": ["bairro"], "zone": ["zona"], "summary": ["ajudas", "maquinas", "empreendedores", "materiais", "descricao", "necessidade_relato"]}, "archive_collections": ["voluntarios", "bases"], "columns": [{"key": "name", "label": "Contato"}, {"key": "phone", "label": "WhatsApp / telefone"}, {"key": "category_label", "label": "Triagem"}, {"key": "stage_label", "label": "Andamento"}, {"key": "summary", "label": "Oferta ou necessidade"}, {"key": "address", "label": "Endereço / bairro"}, {"key": "updated_at", "label": "Última atividade"}], "labels": {"address":"Endereço", "neighborhood":"Bairro", "zone":"Zona", "offer":"Oferta ou necessidade", "search": "Buscar nome, telefone, endereço ou informação", "category": "Categoria", "stage": "Andamento", "all": "Todos", "actions": "Ações", "view": "Ver contato", "delete": "Excluir contato", "new": "Novo cadastro", "empty": "Nenhum contato encontrado.", "loading": "Carregando contatos…", "refresh": "Atualizar", "previous": "Anterior", "next": "Próxima", "page": "Página", "total": "contatos", "close": "Fechar", "summary": "Resumo", "answers": "Respostas", "conversation": "Conversa", "confirmed": "Confirmado", "draft": "Informado no fluxo atual", "profile": "Nome do perfil do WhatsApp", "unnamed": "Nome ainda não informado", "missing": "Não informado", "not_chosen": "Aguardando triagem", "origin": "Origem", "whatsapp": "WhatsApp", "manual": "Cadastro manual", "received": "Entrada", "updated": "Última atividade", "verified_phone": "WhatsApp de origem", "declared_phone": "Telefone informado", "current_question": "Pergunta atual", "progress": "Etapas respondidas", "skipped": "Pulada", "unanswered": "Ainda não respondida", "first": "Primeiro contato", "no_messages": "Não há mensagens registradas para este cadastro.", "older": "Carregar anteriores", "inbound": "Recebida", "outbound": "Enviada", "image": "Imagem", "photo_pending": "Imagem recebida; processamento indisponível ou pendente.", "media_error": "Imagem indisponível. Atualize o detalhe para tentar novamente.", "delete_title": "Excluir este contato?", "delete_description": "O contato sairá da tabela. Cadastros de colaboração e pontos públicos vinculados serão arquivados. Relatos, solicitações e histórico serão preservados. Uma nova mensagem poderá reabrir o atendimento.", "confirm_delete": "Confirmar exclusão", "cancel": "Cancelar", "deleted": "Contato excluído.", "error": "Não foi possível atualizar. Tente novamente.", "stale": "O contato mudou. Atualize antes de excluir.", "busy": "Há mensagem em envio ou com entrega incerta. Aguarde a conciliação antes de excluir.", "linked": "Existe vínculo operacional com este cadastro. Resolva o vínculo antes de excluir.", "forbidden": "Sem permissão para esta operação.", "edit": "Editar cadastro", "history": "Registros confirmados", "none": "Nenhum registro confirmado.", "status": "Situação operacional", "current_cycle": "Respostas do atendimento atual", "all_categories": "As três categorias usam o mesmo acompanhamento; a confirmação mantém cada registro na sua categoria."}, "delivery": {"pending": "Na fila", "sending": "Em envio", "sent": "Aceita pelo WhatsApp", "delivered": "Entregue", "read": "Lida", "failed": "Falha no envio", "uncertain": "Entrega em conciliação", "expired": "Envio encerrado"}}$catalog$::jsonb);
update public.ma_configuracao set documento=jsonb_set(jsonb_set(documento,'{esquemas,voluntarios,label}',to_jsonb('Contatos e atendimentos'::text)),'{esquemas,voluntarios,summary}',to_jsonb('Contatos, triagem e cadastros confirmados nas três categorias.'::text)),versao=versao+1 where id='interface';
